import { AbsoluteFill, useCurrentFrame, spring, interpolate } from 'remotion';

type Props = { line1: string; line2: string; sub: string };

export default function OceanTitle({ line1, line2, sub }: Props) {
  const frame = useCurrentFrame();
  const w = 720, h = 1280;
  const enter = spring({ frame, fps: 30, config: { damping: 14, mass: 0.6, stiffness: 120 } });
  const y1 = interpolate(enter, [0, 1], [120, 0]);
  const y2 = interpolate(enter, [0, 1], [240, 0]);
  const subOpacity = interpolate(frame, [45, 75], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const ring = (frame * 0.08) % 1;

  return (
    <AbsoluteFill style={{ backgroundColor: '#06121f', fontFamily: 'Georgia, serif' }}>
      <svg width={w} height={h} viewBox="0 0 720 1280" style={{ position: 'absolute', inset: 0 }}>
        <defs>
          <radialGradient id="g" cx="0.5" cy="0.45" r="0.6">
            <stop offset="0" stopColor="#38bdf8" stopOpacity="0.45" />
            <stop offset="1" stopColor="#38bdf8" stopOpacity="0" />
          </radialGradient>
          <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#0b2a4a" />
            <stop offset="1" stopColor="#06121f" />
          </linearGradient>
        </defs>
        <rect width="720" height="1280" fill="url(#bg)" />
        <circle cx="360" cy="580" r="380" fill="url(#g)" />
        {Array.from({ length: 6 }).map((_, i) => {
          const phase = (ring + i * 0.14) % 1;
          const r = phase * 520;
          return <circle key={i} cx="360" cy="700" r={r} fill="none" stroke={`rgba(56,189,248,${(1 - phase) * 0.55})`} strokeWidth="3" />;
        })}
      </svg>
      <div style={{ position: 'absolute', top: 220, left: 0, width: w, textAlign: 'center', color: '#f8fafc', fontSize: 110, fontWeight: 700, transform: `translateY(${y1}px)`, opacity: enter }}>{line1}</div>
      <div style={{ position: 'absolute', top: 340, left: 0, width: w, textAlign: 'center', color: '#38bdf8', fontSize: 110, fontWeight: 700, transform: `translateY(${y2}px)`, opacity: enter }}>{line2}</div>
      <div style={{ position: 'absolute', top: 480, left: 0, width: w, textAlign: 'center', color: '#94a3b8', fontSize: 32, letterSpacing: 8, opacity: subOpacity }}>{sub}</div>
    </AbsoluteFill>
  );
}
